widgets_values:
{
  "schema": "h3-director-json-v1",
  "format": {
    "mode": "T2VA",
    "duration_seconds": 5,
    "aspect_ratio": "9:16",
    "total_shots": 3
  },
  "direction": {
    "concept": "Create a 5-second ultra-dynamic cinematic fight scene between two skilled fighters. The scene should feel intense, fast, and visually exciting, like a premium action-movie highlight. Focus on clean choreography, fast movement, strong impact, and dramatic motion, without blood or graphic injury.",
    "visual_style": "High-end cinematic action sequence with sharp contrast, dramatic lighting, fast camera movement, realistic motion blur, powerful body movement, crisp impact moments, and stylish blockbuster energy.",
    "subject": "Two athletic fighters facing each other in a tense close-range combat scene. Both are highly skilled, fast, and physically expressive. Their movement should feel powerful, precise, and believable.",
    "environment": "A dramatic action-ready setting such as a rooftop at night or an industrial warehouse with strong cinematic lighting, sparks, dust, and atmospheric depth. The environment should support action and momentum.",
    "visual_rhythm": "Very fast and aggressive. Each shot must clearly escalate the action. Avoid static posing. Show obvious movement, attack, reaction, and follow-through.",
    "continuity": "Keep the same two fighters throughout. Keep the action continuous and readable as one short intense fight moment."
  },
  "storyboard": [
    {
      "shot": 1,
      "start_seconds": 0.0,
      "end_seconds": 1.5,
      "camera": "Open with a dramatic medium-wide shot, then rush inward with a fast handheld or tracking move as the fighters charge toward each other.",
      "action": "The two fighters sprint in and collide into combat. One throws the first fast punch or kick, and the other blocks immediately. The opening must feel explosive and instantaneous, with strong body movement and no hesitation."
    },
    {
      "shot": 2,
      "start_seconds": 1.5,
      "end_seconds": 3.3,
      "camera": "Cut tighter into the fight with aggressive lateral camera movement and quick reframing to follow the action.",
      "action": "Show a rapid exchange of attacks: punch, block, elbow, dodge, spinning kick, or close-range counterattack. The choreography should be clearly more dynamic than simple pose changes. Bodies must shift position, rotate, and move through space. Add a strong impact beat where one fighter lands a powerful hit or forces the other backward."
    },
    {
      "shot": 3,
      "start_seconds": 3.3,
      "end_seconds": 5.0,
      "camera": "Finish with a strong hero-action climax using a dramatic angle and slight slow-down feeling at the biggest impact moment, then hold briefly on the aftermath pose.",
      "action": "End on the most visually impressive moment: a flying kick, a sweeping takedown, or a powerful final strike that sends the opponent stumbling back. The winner lands in a strong action pose while the other fighter recoils or regains balance. The ending should feel like a clean action highlight, not a complete fight resolution."
    }
  ],
  "audio": {
    "overall_soundscape": "Punchy cinematic fight impacts, cloth movement, footwork, sharp whooshes, body hits, environmental debris sounds, and dramatic action trailer energy.",
    "non_diegetic_music": "A fast high-intensity cinematic action score around 140 BPM with heavy percussion, trailer hits, and strong rhythmic accents matching the fight beats.",
    "sync_basis": {
      "type": "planned_beat",
      "bpm": 140,
      "phase_seconds": 0.0
    }
  },
  "exclusions": [
    "Do not make the scene slow or static.",
    "Do not reduce the fight to just posing or staring.",
    "Do not include blood, gore, or graphic injury.",
    "Do not introduce extra fighters or unrelated comedy elements.",
    "Do not let the camera stay locked without reacting to the action."
  ]
}
